import { API_BASE_URL } from '../config/api';

export interface Post {
  id: string;
  author: string;
  avatarUrl: string;
  imageUrl: string;
  caption: string;
  likes: number;
  comments: number;
  likedByMe: boolean;
}

export async function fetchPosts(): Promise<Post[]> {
  const response = await fetch(`${API_BASE_URL}/feed`);
  if (!response.ok) throw new Error(`Feed failed with status ${response.status}`);
  return (await response.json()) as Post[];
}

export async function likePost(id: string, liked: boolean): Promise<{ likes: number }> {
  const response = await fetch(`${API_BASE_URL}/posts/${id}/like`, {
    method: liked ? 'DELETE' : 'POST',
  });
  if (!response.ok) throw new Error(`Like failed with status ${response.status}`);
  return (await response.json()) as { likes: number };
}

import { useCallback, useEffect, useState } from 'react';
import { View, Text, TouchableOpacity, FlatList, Image, StyleSheet, SafeAreaView, RefreshControl, ActivityIndicator } from 'react-native';
import { fetchPosts, likePost, type Post } from '../services/posts';

const colors = {
  accent: '#f05039',
  bg: '#0f120e',
  surface: '#1a1f1a',
  borderAlt: '#2a2f2a',
  text: '#f5f5f0',
  textSoft: '#d8dbd4',
  textMuted: '#a8ada6',
  danger: '#ff6b5e',
  muted: '#8a8f8a',
}

export function FeedScreen(): JSX.Element {
  const [posts, setPosts] = useState<Post[]>([]);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    try {
      const data = await fetchPosts();
      setPosts(data);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load the feed.');
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  }, []);

  useEffect(() => { void load(); }, [load]);

  const onRefresh = useCallback(() => {
    setRefreshing(true);
    void load();
  }, [load]);

  const toggleLike = useCallback(async (id: string) => {
    const post = posts.find(p => p.id === id);
    if (!post) return;
    setPosts(prev => prev.map(p =>
      p.id === id ? { ...p, likedByMe: !p.likedByMe, likes: p.likes + (p.likedByMe ? -1 : 1) } : p,
    ));
    try {
      const { likes } = await likePost(id, post.likedByMe);
      setPosts(prev => prev.map(p => (p.id === id ? { ...p, likes } : p)));
    } catch {
      setPosts(prev => prev.map(p =>
        p.id === id ? { ...p, likedByMe: !p.likedByMe, likes: p.likes + (p.likedByMe ? 1 : -1) } : p,
      ));
    }
  }, [posts]);

  const renderItem = useCallback(({ item }: { item: Post }) => (
    <View style={styles.card}>
      <View style={styles.header}>
        <Image source={{ uri: item.avatarUrl }} style={styles.avatar} accessibilityLabel={`${item.author} avatar`} />
        <Text style={styles.author}>{item.author}</Text>
      </View>
      <Image source={{ uri: item.imageUrl }} style={styles.photo} resizeMode="cover" accessibilityLabel={item.caption} />
      <Text style={styles.caption}>{item.caption}</Text>
      <View style={styles.actions}>
        <TouchableOpacity onPress={() => void toggleLike(item.id)} accessibilityRole="button" accessibilityLabel={`Like ${item.author}'s post`}>
          <Text style={[styles.like, item.likedByMe && styles.liked]}>{item.likedByMe ? '♥' : '♡'} {item.likes}</Text>
        </TouchableOpacity>
        <TouchableOpacity accessibilityRole="button" accessibilityLabel="View comments">
          <Text style={styles.comments}>💬 {item.comments}</Text>
        </TouchableOpacity>
      </View>
    </View>
  ), [toggleLike]);

  return (
    <SafeAreaView style={styles.safe}>
      {loading && <ActivityIndicator color="{colors.accent}" style={styles.center} />}
      {!loading && error && <Text style={styles.error}>{error}</Text>}
      {!loading && !error && posts.length === 0 && <Text style={styles.empty}>No posts yet.</Text>}
      {!loading && !error && posts.length > 0 && (
        <FlatList
          data={posts}
          renderItem={renderItem}
          keyExtractor={p => p.id}
          contentContainerStyle={styles.list}
          refreshControl={<RefreshControl refreshing={refreshing} onRefresh={onRefresh} tintColor="{colors.accent}" />}
        />
      )}
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  safe: { flex: 1, backgroundColor: colors.bg },
  list: { padding: 16, gap: 16 },
  card: { backgroundColor: colors.surface, borderRadius: 10, overflow: 'hidden' },
  header: { flexDirection: 'row', alignItems: 'center', gap: 10, padding: 12 },
  avatar: { width: 36, height: 36, borderRadius: 18, backgroundColor: colors.borderAlt },
  author: { color: colors.text, fontWeight: '600' },
  photo: { width: '100%', height: 220, backgroundColor: colors.borderAlt },
  caption: { color: colors.textSoft, padding: 12 },
  actions: { flexDirection: 'row', gap: 24, paddingHorizontal: 12, paddingBottom: 12 },
  like: { color: colors.textMuted, fontWeight: '600' },
  liked: { color: colors.accent },
  comments: { color: colors.textMuted },
  center: { marginTop: 40 },
  error: { color: colors.danger, textAlign: 'center', marginTop: 24 },
  empty: { color: colors.muted, textAlign: 'center', marginTop: 24 },
});
